package com.oms.order.service;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.oms.order.service.ExchangeService.map;
import static com.oms.order.service.OrderValues.*;
class OrderPlatformLogWorkspaceTest {
    ExchangeServiceTest fixture;OrderPlatformLogWorkspace workspace;long exchange;
    @BeforeAll static void start(){ExchangeServiceTest.start();}
    @BeforeEach void setup(){fixture=new ExchangeServiceTest();fixture.reset();workspace=new OrderPlatformLogWorkspace(fixture.repo);exchange=fixture.ingest(fixture.source());}
    @Test void exchangeLookupUsesOnlyItsOwnApplicationAndNeverBroadensToEveryCaseOnTheOrder(){String sn=text(fixture.service.row("VERIFY",exchange,false),"exchange_sn");List<Map<String,Object>> refs=workspace.resolve("VERIFY",map("type","EXCHANGE","number",sn));assertTrue(refs.contains(map("type","PLATFORM_EXCHANGE","number","123456")));assertFalse(refs.stream().anyMatch(r->"PLATFORM_TID".equals(r.get("type"))));assertEquals(1,workspace.resolve("OTHER",map("type","EXCHANGE","number",sn)).size());}
    @Test void businessProgressIsCompanyScopedAndDoesNotWriteFacts(){String sn=text(fixture.service.row("VERIFY",exchange,false),"exchange_sn");List<Map<String,Object>> refs=Arrays.asList(map("type","EXCHANGE","number",sn),map("type","OMS_ORDER","number","SO_EXCHANGE"));assertEquals(2,workspace.states("VERIFY",refs).size());assertTrue(workspace.states("OTHER",refs).isEmpty());assertEquals(1,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order",Integer.class));assertEquals(5,fixture.db.queryForObject("SELECT shipped_quantity FROM oms_order_shipment_line",Integer.class));}
    @Test void platformDisputeCanResolveProgressAfterListCallCreatedLocalCase(){List<Map<String,Object>> rows=workspace.states("VERIFY",Collections.singletonList(map("type","PLATFORM_EXCHANGE","number","123456")));assertEquals(1,rows.size());assertEquals(exchange,number(rows.get(0),"id"));assertEquals("EXCHANGE",rows.get(0).get("business_type"));}
    @Test void outboundContextContainsExactBusinessReferencesAndNoRawPlatformSnapshot(){Map<String,Object> context=workspace.exchangeContext("VERIFY",1,map("dispute_id","123456"));String body=encode(context);assertTrue(body.contains("EXCHANGE"));assertTrue(body.contains("SO_EXCHANGE"));assertFalse(body.contains("raw_payload"));assertFalse(context.containsKey("operation_id"),"Independent reads must not merge into one lifetime chain");assertEquals("order",context.get("source_service"));assertThrows(IllegalArgumentException.class,()->workspace.resolve("VERIFY",map("type","EXCHANGE","number","' OR 1=1")));}
    @Test void submittingAndConfirmingOneWriteShareAnOperationWithoutUsingMutableControlVersion(){fixture.db.update("UPDATE oms_exchange SET platform_operation='PENDING',platform_request='{}',approved_version=1 WHERE id=?",exchange);Map<String,Object> first=workspace.exchangeContext("VERIFY",1,map("dispute_id","123456"));fixture.db.update("UPDATE oms_exchange SET control_version=control_version+1 WHERE id=?",exchange);assertEquals(first.get("operation_id"),workspace.exchangeContext("VERIFY",1,map("dispute_id","123456")).get("operation_id"));assertTrue(first.containsKey("operation_id"));}
    @Test void automaticNumberResolutionFindsExactAliasesAndExchangeShipmentWithoutStockWrites(){String sn=text(fixture.service.row("VERIFY",exchange,false),"exchange_sn");assertTrue(workspace.resolve("VERIFY",map("type","AUTO","number",sn)).contains(map("type","PLATFORM_EXCHANGE","number","123456")));assertTrue(workspace.resolve("VERIFY",map("type","AUTO","number","123456")).contains(map("type","EXCHANGE","number",sn)));fixture.db.update("UPDATE oms_order_shipment SET business_type='EXCHANGE',exchange_id=? WHERE id=?",exchange,fixture.shipment);assertTrue(workspace.resolve("VERIFY",map("type","AUTO","number","XS_EXCHANGE")).contains(map("type","EXCHANGE","number",sn)));assertFalse(workspace.resolve("OTHER",map("type","AUTO","number","XS_EXCHANGE")).contains(map("type","EXCHANGE","number",sn)));assertEquals(5,fixture.db.queryForObject("SELECT shipped_quantity FROM oms_order_shipment_line",Integer.class));}
    @Test void platformProgressIncludesBusinessFactsEvenWhenNoInteractionWasMade(){String sn=text(fixture.service.row("VERIFY",exchange,false),"exchange_sn");fixture.db.update("UPDATE oms_exchange SET source_kind='INTERNAL',state='COMPLETED',stage='FINISHED' WHERE id=?",exchange);fixture.db.update("UPDATE oms_order_shipment SET business_type='EXCHANGE',exchange_id=? WHERE id=?",exchange,fixture.shipment);List<Map<String,Object>> rows=workspace.states("VERIFY",Arrays.asList(map("type","EXCHANGE","number",sn),map("type","PLATFORM_EXCHANGE","number","123456")));assertEquals(2,rows.size());for(Map<String,Object> r:rows){assertEquals("INTERNAL",r.get("source_kind"));assertEquals(5,number(r,"platform_shipped_quantity"));assertEquals(0,number(r,"platform_packaged_quantity"));assertEquals("NONE",r.get("platform_operation"));assertFalse(r.containsKey("platform_request"));assertFalse(r.containsKey("payload"));}assertEquals(1,fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment",Integer.class));}
}
